package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal
var WsTotal decimal.Decimal
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec

var loanFile *os.File
var scanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseDecimalField(s string, scale int) decimal.Decimal {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	cleaned := b.String()
	if cleaned == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(cleaned)
	if err != nil {
		return decimal.Zero
	}
	if scale != 0 {
		d = d.Shift(int32(-scale))
	}
	return d
}

func parseIntField(s string) int64 {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	cleaned := b.String()
	if cleaned == "" {
		return 0
	}
	var v int64
	for _, ch := range cleaned {
		v = v*10 + int64(ch-'0')
	}
	return v
}

func applyOverflow(d decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if intDigits+scale <= 0 {
		return decimal.Zero
	}
	neg := d.IsNegative()
	if neg {
		d = d.Neg()
	}
	scaled := d.Shift(int32(scale)).Truncate(0)
	modulus := decimal.NewFromInt(1).Shift(int32(intDigits + scale))
	if scaled.Cmp(modulus) >= 0 {
		scaled = scaled.Mod(modulus)
	}
	res := scaled.Shift(int32(-scale))
	if neg {
		res = res.Neg()
	}
	return res
}

func storeRounded(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	rounded := val.Round(int32(scale))
	return applyOverflow(rounded, intDigits, scale)
}

func storeTrunc(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	truncated := val.Truncate(int32(scale))
	return applyOverflow(truncated, intDigits, scale)
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx != -1 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracSlots++
		}
	}
	isNegative := val.IsNegative()
	if isNegative {
		val = val.Neg()
	}
	truncated := val.Truncate(int32(fracSlots))
	sFixed := truncated.StringFixed(int32(fracSlots))
	var intStr, fracStr string
	if fracSlots > 0 {
		parts := strings.SplitN(sFixed, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracSlots)
		}
		if len(fracStr) < fracSlots {
			fracStr += strings.Repeat("0", fracSlots-len(fracStr))
		} else if len(fracStr) > fracSlots {
			fracStr = fracStr[:fracSlots]
		}
	} else {
		if strings.Contains(sFixed, ".") {
			parts := strings.SplitN(sFixed, ".", 2)
			intStr = parts[0]
		} else {
			intStr = sFixed
		}
		fracStr = ""
	}
	// handle sign in intStr (should not happen for positive truncated)
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	if strings.HasPrefix(intStr, "+") {
		intStr = intStr[1:]
	}
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	} else if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}

	picRunes := []rune(picture)
	out := make([]rune, len(picRunes))
	copy(out, picRunes)

	intPlaceholderIdxs := []int{}
	fracPlaceholderIdxs := []int{}
	for i, ch := range picRunes {
		if dotIdx != -1 {
			if i < dotIdx && (ch == 'Z' || ch == '9') {
				intPlaceholderIdxs = append(intPlaceholderIdxs, i)
			} else if i > dotIdx && (ch == 'Z' || ch == '9') {
				fracPlaceholderIdxs = append(fracPlaceholderIdxs, i)
			}
		} else {
			if ch == 'Z' || ch == '9' {
				intPlaceholderIdxs = append(intPlaceholderIdxs, i)
			}
		}
	}
	for k, idx := range intPlaceholderIdxs {
		if k < len(intStr) {
			out[idx] = rune(intStr[k])
		}
	}
	for k, idx := range fracPlaceholderIdxs {
		if k < len(fracStr) {
			out[idx] = rune(fracStr[k])
		} else {
			out[idx] = '0'
		}
	}

	upper := dotIdx
	if dotIdx == -1 {
		upper = len(picRunes)
	}
	foundSignificant := false
	for i := 0; i < upper; i++ {
		orig := picRunes[i]
		switch orig {
		case 'Z':
			if !foundSignificant && out[i] == '0' {
				out[i] = ' '
			} else {
				if out[i] != '0' && out[i] != ' ' {
					foundSignificant = true
				} else if out[i] == '0' && foundSignificant {
					// keep zero, still significant
				} else if out[i] == '0' && !foundSignificant {
					// this case should have been suppressed above, but if it wasn't (should not happen)
					// treat as not significant
				}
				// if digit is non-zero, mark significant
				if out[i] != ' ' && out[i] != '0' {
					foundSignificant = true
				}
			}
		case '9':
			if out[i] != '0' {
				foundSignificant = true
			}
		case ',':
			if !foundSignificant {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		}
	}
	_ = isNegative
	return string(out)
}

func padTruncate(s string, length int) string {
	if len(s) > length {
		return s[:length]
	}
	if len(s) < length {
		return s + strings.Repeat(" ", length-len(s))
	}
	return s
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		rec := padTruncate(line, 21)
		loanRec.LrAcct = rec[0:6]
		principalStr := rec[6:15]
		rateStr := rec[15:19]
		yearsStr := rec[19:21]
		loanRec.LrPrincipal = parseDecimalField(principalStr, 2)
		loanRec.LrRate = parseDecimalField(rateStr, 2)
		loanRec.LrYears = parseIntField(yearsStr)
		WsEofFlag = "N"
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	WsInterest = storeRounded(raw, 9, 2)

	sum := WsTotal.Add(WsInterest)
	WsTotal = storeTrunc(sum, 11, 2)

	WsCount = (WsCount + 1) % 100000

	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	line := loanRec.LrAcct + " " + WsPrinEd + " " + WsIntEd
	fmt.Fprintln(os.Stdout, line)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount%100000)
	fmt.Fprintln(os.Stdout, "RECORDS: "+countStr)
	fmt.Fprintln(os.Stdout, "TOTAL INTEREST: "+WsTotalEd)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		WsEofFlag = "Y"
		SummaryPara()
		return
	}
	loanFile = f
	defer f.Close()
	scanner = bufio.NewScanner(f)
	// allow long lines if needed
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 4096)
	scanner.Buffer(buf, maxCap)

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
}

func main() {
	MainPara()
}

